import hydra from hydra.utils import instantiate
@hydra.main(config_name="my_app", config_path=None, version_base="1.2") def trainer_task_fn(cfg): model = instantiate(cfg.model) data = instantiate(cfg.data) partial_optim = instantiate(cfg.partial_optim) trainer = instantiate(cfg.trainer)
optim = partial_optim(model.parameters()) trainer(model, optim, data).fit(cfg.num_epochs)
if __name__ == "__main__": trainer_task_fn()

from dataclasses import dataclass
from hydra_zen import store

profile_store = store(group="profile")

# Adds two store entries under the "profile" group of the store
# with configured defaults for `has_root`
@profile_store(name="admin", has_root=True)
@profile_store(name="basic", has_root=False)
@dataclass
class Profile:
    username: str
    schema: str
    has_root: bool


db_store = store(group="database")

# calls `builds(profile_database, [...])` under the hood and
# adds the config to the store under the "profile" group
@db_store(name="database")
@db_store(name="test_database", size=1)
def profile_database(size):
    ...

from dataclasses import dataclass, field

@dataclass
class A:
   ...

@dataclass
class NoLongerValid:
   number: int = 1
   nested: A = A()  # will raise at runtime due to mutable default

@dataclass
class IsOK:
   number: int = 1
   nested: A = field(default_factory=lambda: A())

from dataclasses import dataclass, field from typing import Any
from hydra_zen import builds from hydra_zen.typing import Builds
@dataclass class Config: # This is still OK builds_dict: Builds[type[dict[Any, Any]]] = builds(dict)()

